class Solution:
    def longestRun(self, nums):
        if not nums:
            return 0
        best = 1
        current = 1
        for i in range(1, len(nums)):
            if nums[i] == nums[i - 1]:
                current += 1
                best = max(best, current)
            else:
                current = 1
        return best

